export const applyGitHubMediaTransferBodyExpectedHeadShaMax = 64;





export const ApplyGitHubMediaTransferBody = zod.object({
  "owner": zod.string().min(1).max(applyGitHubMediaTransferBodyOwnerMax),
  "repo": zod.string().min(1).max(applyGitHubMediaTransferBodyRepoMax),
  "branch": zod.string().min(1).max(applyGitHubMediaTransferBodyBranchMax),
  "path": zod.string().min(1).max(applyGitHubMediaTransferBodyPathMax),
  "revision": zod.number().int().min(1),
  "direction": zod.enum(['to_repository', 'from_repository']),
  "expectedHeadSha": zod.string().min(applyGitHubMediaTransferBodyExpectedHeadShaMin).max(applyGitHubMediaTransferBodyExpectedHeadShaMax),
  "expectedFiles": zod.array(zod.object({
  "assetId": zod.string(),
  "path": zod.string(),
  "status": zod.enum(['ready', 'already_current', 'remote_conflict', 'storage_conflict', 'missing_remote', 'missing_local', 'path_conflict', 'unsupported_type', 'too_large', 'invalid_record']),
  "localSha256": zod.string().nullable(),
  "remoteSha256": zod.string().nullable(),
  "remoteBlobSha": zod.string().nullable()
})),
  "selectedAssetIds": zod.array(zod.string().min(1)).min(1),
  "confirmed": zod.boolean(),
  "replaceRemoteConflicts": zod.boolean()
})

export const applyGitHubMediaTransferResponseFilesTransferredMin = 0;

export const applyGitHubMediaTransferResponseFilesAlreadyCurrentMin = 0;



export const ApplyGitHubMediaTransferResponse = zod.object({
  "direction": zod.enum(['to_repository', 'from_repository']),
  "owner": zod.string(),
  "repo": zod.string(),
  "branch": zod.string(),
  "issuePath": zod.string(),
  "filesTransferred": zod.number().int().min(applyGitHubMediaTransferResponseFilesTransferredMin),
  "filesAlreadyCurrent": zod.number().int().min(applyGitHubMediaTransferResponseFilesAlreadyCurrentMin),
  "skippedFiles": zod.array(zod.object({
  "assetId": zod.string(),
  "assetName": zod.string(),
  "reason": zod.string()
})),
  "commitSha": zod.string().nullable(),
  "htmlUrl": zod.string().url().nullable()
})


export const ListGitHubMediaReplacementAuditsResponse = zod.object({
  "replacements": zod.array(zod.object({
  "id": zod.number().int(),
  "accountId": zod.string(),
  "at": zod.coerce.date(),
  "owner": zod.string(),
  "repo": zod.string(),
  "branch": zod.string(),
  "issuePath": zod.string(),
  "files": zod.array(zod.object({
  "assetId": zod.string(),
  "path": zod.string(),
  "priorRemoteFingerprint": zod.object({
  "remoteSha256": zod.string().nullable(),
  "remoteBlobSha": zod.string().nullable()
})
})),
  "commitSha": zod.string()
}))
})


export const ListGitHubMediaRestoresResponse = zod.object({
  "restores": zod.array(zod.object({
  "id": zod.number().int(),
  "at": zod.coerce.date(),
  "owner": zod.string(),
  "repo": zod.string(),
  "branch": zod.string(),
  "issuePath": zod.string(),
  "assetId": zod.string(),
  "fileName": zod.string(),
  "filePath": zod.string(),
  "actorDisplayName": zod.string(),
  "outcome": zod.enum(['completed', 'failed']),
  "failureReason": zod.string().nullable()
}))
})



export const requestUploadUrlBodySizeMax = 20971520;




export const RequestUploadUrlBody = zod.object({
  "name": zod.string().min(1),
  "size": zod.number().int().min(1).max(requestUploadUrlBodySizeMax),
  "contentType": zod.string().min(1)
})

export const RequestUploadUrlResponse = zod.object({
  "uploadURL": zod.string(),
  "objectPath": zod.string()
})


export const GetStorageObjectParams = zod.object({
  "objectPath": zod.coerce.string()
})

export const GetStorageObjectResponse = zod.unknown()


export const GetCurrentAuthUserResponse = zod.object({
  "user": zod.union([zod.object({
  "id": zod.string(),
  "email": zod.string().nullable(),
  "firstName": zod.string().nullable(),
  "lastName": zod.string().nullable(),
  "profileImageUrl": zod.string().nullable()
}),zod.null()]),
  "roles": zod.array(zod.enum(['myrtle_editor', 'newsroom_admin']))
})


export const LoginResponse = zod.void()


export const OidcCallbackResponse = zod.void()


export const LogoutResponse = zod.void()


export const ExchangeMobileAuthorizationCodeBody = zod.object({
  "code": zod.string(),
  "code_verifier": zod.string(),
  "redirect_uri": zod.string(),
  "nonce": zod.string().optional(),
  "state": zod.string()
})

export const ExchangeMobileAuthorizationCodeResponse = zod.object({
  "token": zod.string()
})


export const LogoutMobileSessionResponse = zod.object({
  "success": zod.boolean()
})


